-- woolworths-liberty-promenade-mitchells-plain (owner)
UPDATE businesses SET description = 'Woolworths Liberty Promenade is the Woolworths fashion store at Shop 23 in Liberty Promenade, on the corner of AZ Berman Drive and Morgenster Road in Mitchells Plain. It gives shoppers in Mitchells Plain and the surrounding Cape Flats a local place to buy Woolworths clothing without travelling into town.

The store dresses the whole family, with a range that runs from everyday wardrobe staples to smarter, more current pieces for work, weekends and special occasions. Woolworths clothing is known for the quality of its fabrics and for lasting well through regular wear and washing, which is why many local shoppers come back to it when they want style and value in the same purchase. Because it sits inside the mall, a visit is easy to combine with other errands at Liberty Promenade. Woolworths is at Shop 23, Liberty Promenade, corner AZ Berman Drive and Morgenster Road, Mitchells Plain.', description_enriched_at = datetime('now') WHERE slug = 'woolworths-liberty-promenade-mitchells-plain' AND description = 'Woolworths is a supermarket inside Liberty Promenade in Mitchells Plain.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
