UPDATE businesses SET description = 'Fashion City is a fashion and clothing store in the Golden Acre Shopping Centre in the heart of the Cape Town CBD. It caters for style-conscious city shoppers, commuters and locals who want to update their wardrobe affordably.

The store stocks a wide mix of contemporary clothing, from eye-catching statement pieces for a night out or special occasion to the everyday basics people wear to work and on weekends. Shoes and accessories are displayed alongside the clothing, so customers can match an outfit and complete their look in a single visit. Its location in Golden Acre, next to the city''s main bus, taxi and train connections, makes it easy for commuters to browse on their way to or from work or during a lunch break. Fashion City is in Golden Acre Shopping Centre, 9 Adderley Street, Cape Town.', description_enriched_at = datetime('now') WHERE slug = 'fashion-city-golden-acre-cape-town-cbd' AND description = 'Fashion City is a fashion and clothing retailer inside Golden Acre Shopping Centre in the Cape Town CBD.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
